#include <bits/stdc++.h>
using namespace std;using U=uint64_t;const U ALL=(1ULL<<50)-1;int C=5,HH=3,M=10;U R[10],sup[50],hit[50][1024];int F[]={23,86,91,101,123,157,175,203,211,243,245,281,287,299,301,327,346,367,371,389,394,410,412,447,457,460,486,491,567,599,602,613,615,646,673,697,701,718,721,753,788,789,828,833,857,867,949,965,980,1005};
struct S{U a;vector<U> l;int e,h;bool live;int p=0;bool operator==(S const&b)const{return a==b.a&&l==b.l&&e==b.e&&h==b.h&&live==b.live&&p==b.p;}};struct H{size_t operator()(S const&s)const{U x=s.a*31+s.e*8+s.h*2+s.live+s.p*1777;for(U z:s.l)x^=z+0x9e3779b97f4a7c15ULL+(x<<6)+(x>>2);return x;}};
unordered_map<S,int,H> memo, abstractMemo;bool finiteMode=false;long long calls=0;auto st=chrono::steady_clock::now();int norm(S&s){bool change=true;while(change&&s.a&&s.h>0){change=false;U a=s.a;while(a){int i=__builtin_ctzll(a);a&=a-1;int b=0;for(U l:s.l)b+=!(l>>i&1);if(b>s.h){s.a&=~(1ULL<<i);change=true;}}vector<U> l;for(U z:s.l){z&=s.a;if(!z){s.h--;s.e--;change=true;}else if(z!=s.a)l.push_back(z);}s.l.swap(l);}sort(s.l.begin(),s.l.end());int low=0;U a=s.a;while(a){int i=__builtin_ctzll(a);a&=a-1;int b=0;for(U l:s.l)b+=!(l>>i&1);low+=(b<s.h);}return low;}
bool bound(S const&s){if(s.h<=0)return true;U a=s.a;while(a){int i=__builtin_ctzll(a);a&=a-1;int b=0;vector<U> opt;for(U l:s.l)if(!(l>>i&1))b++;else opt.push_back(l);if(b>=s.h)continue;int ex=C-s.e+b;if(ex<0)return false;if(ex>=3)continue;int k=max(0,(int)opt.size()-(s.h-1-b));U vs0=sup[i]&s.a;if(!vs0)continue;for(int a=0;a<(1<<(int)opt.size());a++){if(__builtin_popcount((unsigned)a)!=k)continue;U vs=vs0;for(int j=0;j<(int)opt.size();j++)if(a>>j&1)vs&=opt[j];if(!vs)continue;bool ok=false;if(ex==1){for(int t=0;t<10;t++)if(!(vs&~hit[i][1<<t])){ok=true;break;}}else if(ex==2){for(int t=0;t<10&&!ok;t++)for(int r=t+1;r<10;r++)if(!(vs&~hit[i][(1<<t)|(1<<r)])){ok=true;break;}}if(!ok)return false;}}return true;}
bool sat(U a,vector<U>const& probes,int rem);
bool terminal(S const&s){int rem=M+C-s.e-s.p-(HH-s.h);vector<U> probes;for(U l:s.l)for(int t=0;t<10;t++)probes.push_back(l&R[t]);if(s.live||M-s.p-(HH-s.h)>(int)s.l.size())for(int t=0;t<10;t++)probes.push_back(s.a&R[t]);sort(probes.begin(),probes.end());probes.erase(unique(probes.begin(),probes.end()),probes.end());return sat(s.a,probes,rem);}
struct Opt{S x,y;int nx,ny,j,t,score;};
bool solve(S s){calls++;int low=norm(s);if(!low)return !finiteMode||terminal(s);if(!bound(s))return false;if(__builtin_popcountll(s.a)==1)return true;auto it=memo.find(s);if(it!=memo.end())return it->second>=0;if(calls%1000000==0)cerr<<calls<<" memo "<<memo.size()<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-st).count()<<endl;
vector<Opt> opts;for(int j=-1;j<=(int)s.l.size();j++){if(j==-1&&!s.live)continue;if(finiteMode&&j==(int)s.l.size()&&M-s.p-(HH-s.h)<=(int)s.l.size())continue;if(j>0&&j<(int)s.l.size()&&s.l[j]==s.l[j-1])continue;for(int t=0;t<10;t++){U p=s.a&R[t];if(j>=0&&j<(int)s.l.size())p&=s.l[j];if(!p)continue;if((j==-1||(j==(int)s.l.size()&&s.live))&&p==s.a)continue;S x=s,y=s;x.e++;if(j==-1){x.a&=~R[t];y.a=p;y.e++;}else{if(j==(int)s.l.size())x.l.push_back(s.a&~R[t]);else{x.l[j]&=~R[t];y.l.erase(y.l.begin()+j);}y.a=p;y.live=true;if(finiteMode)y.p++;}int nx=norm(x),ny=norm(y);if(!x.a||!y.a||!bound(x)||!bound(y)||(finiteMode&&((!nx&&!terminal(x))||(!ny&&!terminal(y)))))continue;int score=max(nx,ny)*100+nx+ny;opts.push_back({x,y,nx,ny,j,t,score});}}
sort(opts.begin(),opts.end(),[](auto&a,auto&b){return tie(a.score,a.j,a.t)<tie(b.score,b.j,b.t);});if(finiteMode){S q=s;q.p=0;auto i=abstractMemo.find(q);if(i!=abstractMemo.end()&&i->second>=0){int a=i->second;auto j=find_if(opts.begin(),opts.end(),[&](auto&o){return (o.j+1)*10+o.t==a;});if(j!=opts.end())rotate(opts.begin(),j,j+1);}}for(auto&o:opts){bool ok=o.nx>=o.ny?(solve(o.x)&&solve(o.y)):(solve(o.y)&&solve(o.x));if(ok){memo[s]=(o.j+1)*10+o.t;return true;}}memo[s]=-1;return false;}
void replay(int m);
int main(int argc,char**argv){if(argc>1)HH=atoi(argv[1]);if(argc>2)C=atoi(argv[2]);if(argc>3)M=atoi(argv[3]);for(int t=0;t<10;t++)for(int i=0;i<50;i++)if(F[i]>>t&1)R[t]|=1ULL<<i;for(int i=0;i<50;i++)for(int v=0;v<50;v++)if(i!=v&&(F[v]&F[i])==F[i]){sup[i]|=1ULL<<v;for(int t=0;t<1024;t++)if(t&(F[v]^F[i]))hit[i][t]|=1ULL<<v;}S s{ALL,{},0,HH,false};bool ok=solve(s);cout<<"abstract "<<ok<<" "<<calls<<" "<<memo.size()<<endl;if(!ok)return 0;abstractMemo.swap(memo);finiteMode=true;calls=0;ok=solve(s);cout<<HH<<","<<C<<","<<ok<<","<<calls<<","<<memo.size()<<endl;if(ok)replay(M);}
// Saturated exact depth oracle over physical probe masks (no state-changing normalizer).
bool sat(U a,vector<U>const& probes,int rem){if(__builtin_popcountll(a)<=1)return true;if(rem<=0||__builtin_popcountll(a)>(1<<rem))return false;vector<pair<int,U>> opts;for(U p:probes){U x=a&p,y=a^x;if(!x||!y)continue;if(x>y)swap(x,y);int n=max(__builtin_popcountll(x),__builtin_popcountll(y));if(n<=(1<<(rem-1)))opts.push_back({n,x});}sort(opts.begin(),opts.end());opts.erase(unique(opts.begin(),opts.end()),opts.end());for(auto [n,x]:opts)if(sat(x,probes,rem-1)&&sat(a^x,probes,rem-1))return true;return false;}

void replay(int m){long long pass=0,failfresh=0,failsat=0,failbudget=0,tot=0;int maxd=0,reused=0;for(int u:F)for(int H=0;H<(1<<m);H++)if(__builtin_popcount((unsigned)H)<=HH){vector<int> neg(m),pos(m);int d=0;auto probe=[&](int t,int j){assert(j>=0&&j<m);int bit=1<<t;assert(!((neg[j]|pos[j])&bit));d++;if((u&bit)&&!(H>>j&1)){pos[j]|=bit;return true;}neg[j]|=bit;return false;};while(true){U a=0;array<int,50> forced{};for(int i=0;i<50;i++){bool ok=true;int b=0;for(int j=0;j<m;j++){if(pos[j]){if((pos[j]&F[i])!=pos[j]||(neg[j]&F[i])){ok=false;break;}}else b+=!!(neg[j]&F[i]);}if(ok&&b<=HH){a|=1ULL<<i;forced[i]=b;}}assert(a&(1ULL<<(find(F,F+50,u)-F)));int known=0,confirmed=0,live=-1,fresh=-1,low=0;for(int i=0;i<50;i++)if(a>>i&1)low+=forced[i]<HH;vector<pair<U,int>> cols;vector<int> unknown;vector<U> masks(m);for(int j=0;j<m;j++){if(pos[j]){confirmed++;live=j;masks[j]=a;continue;}U l=a;for(int i=0;i<50;i++)if((l>>i&1)&&(neg[j]&F[i]))l&=~(1ULL<<i);masks[j]=l;if(!l)known|=1<<j;else{unknown.push_back(j);if(l!=a)cols.push_back({l,j});else if(fresh<0||!neg[j])fresh=j;}}sort(cols.begin(),cols.end());int b=__builtin_popcount((unsigned)known);S s{a,{},d-confirmed-b,HH-b,live>=0,confirmed};for(auto x:cols)s.l.push_back(x.first);
if(__builtin_popcountll(a)==1){int recovered=F[__builtin_ctzll(a)],rh=known;if(!low){for(int j:unknown)assert(!(neg[j]&recovered));}else for(int j:unknown){int t=__builtin_ctz((unsigned)recovered);assert(!(neg[j]>>t&1));if(!probe(t,j))rh|=1<<j;}assert(recovered==u&&rh==H);if(d>m+C)failbudget++;else{pass++;tot+=d;maxd=max(maxd,d);}break;}
if(!low){vector<U> probes;for(U l:masks)for(int t=0;t<10;t++)if(l&R[t])probes.push_back(l&R[t]);sort(probes.begin(),probes.end());probes.erase(unique(probes.begin(),probes.end()),probes.end());int rem=m+C-d;if(!sat(a,probes,rem)){failsat++;break;}while(__builtin_popcountll(a)>1){bool found=false;for(int j=0;j<m&&!found;j++)for(int t=0;t<10&&!found;t++){U x=a&masks[j]&R[t],y=a^x;if(!x||!y)continue;if(sat(x,probes,rem-1)&&sat(y,probes,rem-1)){bool q=probe(t,j);a=q?x:y;rem--;found=true;}}assert(found);}int recovered=F[__builtin_ctzll(a)],rh=0;for(int j=0;j<m;j++)if(!(masks[j]&a))rh|=1<<j;assert(recovered==u&&rh==H&&d<=m+C);pass++;tot+=d;maxd=max(maxd,d);break;}
auto it=memo.find(s);assert(it!=memo.end()&&it->second>=0);int j=it->second/10-1,t=it->second%10;if(j==-1)j=live;else if(j==(int)cols.size()){j=fresh;if(j<0){failfresh++;break;}if(neg[j])reused++;}else j=cols[j].second;assert(j>=0);probe(t,j);if(d>m+C){failbudget++;break;}}
}cout<<"replay "<<m<<" pass "<<pass<<" failfresh "<<failfresh<<" failsat "<<failsat<<" failbudget "<<failbudget<<" max "<<maxd<<" total "<<tot<<" reused "<<reused<<endl;}
